const API = "https://stream.saysaymusic.com";
const COVER_BASE64 = "";
const FALLBACK = {
  track_id: "6c5e1a0028f87a98016464d428f34b75e37c93f9",
  title: "What If Hope Went Viral!",
  artist: "SaySayCreator",
  subject: "Entertainment",
  cover_url: "https://app.saysaymusic.com/free-song-cover.jpg"
};

function esc(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function coverResponse() {
  const binary = atob(COVER_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Response(bytes, {
    headers: {
      "Content-Type": "image/jpeg",
      "Cache-Control": "public, max-age=604800",
      "X-Content-Type-Options": "nosniff"
    }
  });
}

async function getFeatured() {
  try {
    const response = await fetch(API + "/api/featured-song", { headers: { Accept: "application/json" } });
    const data = await response.json();
    return data && data.featured && data.featured.track_id ? data.featured : FALLBACK;
  } catch {
    return FALLBACK;
  }
}

function baseStyles() {
  return ":root{color-scheme:dark;--gold:#ffbf00;--green:#12c96b;--panel:#0b0e12;--border:rgba(255,191,0,.3)}*{box-sizing:border-box}body{margin:0;background:#050607;color:#f8f8f8;font-family:Arial,Helvetica,sans-serif;min-height:100vh}header{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:10px 20px;background:#090b0e;border-bottom:1px solid var(--border)}.brand{display:flex;align-items:center;gap:12px;color:#fff;text-decoration:none;font-size:24px;font-weight:800}.brand img{width:56px;height:56px;object-fit:contain}.app-link,.primary{color:#0b0b0b;background:linear-gradient(#ffd352,#ffb900);padding:12px 18px;border:0;border-radius:10px;text-decoration:none;font-weight:800}footer{text-align:center;color:#9ba7b2;padding:0 16px 24px;font-size:13px}@media(max-width:560px){header{padding:9px 12px}.brand{font-size:18px}.brand img{width:42px;height:42px}.app-link{padding:10px 12px;font-size:13px}}";
}

async function publicPage() {
  const song = await getFeatured();
  const streamUrl = API + "/api/stream/" + encodeURIComponent(song.track_id);
  const coverUrl = song.cover_url || FALLBACK.cover_url;
  const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<title>' + esc(song.title) + ' | SaySayMusic</title><meta name="description" content="Listen to the complete featured song free on SaySayMusic.">' +
    '<meta property="og:title" content="' + esc(song.title) + '"><meta property="og:description" content="Listen to the complete featured song free on SaySayMusic.">' +
    '<meta property="og:type" content="music.song"><meta property="og:url" content="https://app.saysaymusic.com/free-song"><meta property="og:image" content="' + esc(coverUrl) + '"><meta name="twitter:card" content="summary_large_image">' +
    '<style>' + baseStyles() + 'main{width:min(100% - 28px,620px);margin:28px auto;padding:24px;background:linear-gradient(180deg,#0e1116,#080a0d);border:1px solid var(--border);border-radius:20px;text-align:center}.eyebrow{color:var(--gold);font-size:14px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;margin-bottom:16px}.cover{display:block;width:min(100%,470px);aspect-ratio:1/1;object-fit:cover;margin:0 auto;border-radius:18px;border:1px solid var(--border);box-shadow:0 18px 48px rgba(0,0,0,.48)}h1{font-size:clamp(28px,6vw,42px);line-height:1.05;margin:22px 0 8px}.meta{color:#c4ccd4;margin-bottom:18px}audio{width:100%;min-height:48px;margin-top:4px}.free{color:#dfffea;background:rgba(18,201,107,.12);border:1px solid rgba(18,201,107,.48);border-radius:10px;padding:12px;margin:16px 0}.actions{display:grid;grid-template-columns:1fr 1fr;gap:10px}.actions a{padding:13px 12px;border-radius:10px;text-decoration:none;font-weight:800}.explore{background:var(--gold);color:#090909}.account{border:1px solid var(--border);color:#fff;background:#11151b}@media(max-width:560px){main{margin:14px auto;padding:14px;border-radius:15px}.actions{grid-template-columns:1fr}}</style></head><body>' +
    '<header><a class="brand" href="https://app.saysaymusic.com/"><img src="https://audio.saysaymusic.com/Logo_New1.png" alt=""><span>SaySayMusic</span></a><a class="app-link" href="https://app.saysaymusic.com/">Open SaySayApp</a></header>' +
    '<main><div class="eyebrow">Free Song of the Week</div><img class="cover" src="' + esc(coverUrl) + '" alt="' + esc(song.title) + ' cover"><h1>' + esc(song.title) + '</h1><div class="meta">' + esc(song.artist) + (song.subject ? ' · ' + esc(song.subject) : '') + '</div>' +
    '<audio controls preload="metadata" controlslist="nodownload noplaybackrate" src="' + esc(streamUrl) + '">Your browser does not support audio playback.</audio><div class="free">Full song · No login · No listening limit</div>' +
    '<div class="actions"><a class="explore" href="https://app.saysaymusic.com/">Explore SaySayApp</a><a class="account" href="https://app.saysaymusic.com/?login=1">Create a Free Account</a></div></main><footer>SaySayMusic — Education Through Melody</footer></body></html>';
  return new Response(html, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", "Referrer-Policy": "strict-origin-when-cross-origin" } });
}

function adminPage() {
  const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Free Song of the Week | SaySayMusic Studio</title><style>' + baseStyles() +
    'main{width:min(100% - 28px,900px);margin:28px auto}.panel{background:linear-gradient(180deg,#0e1116,#080a0d);border:1px solid var(--border);border-radius:18px;padding:22px}h1{margin:0 0 8px}.muted{color:#aab5bf}.field{margin-top:18px}label{display:block;font-weight:800;margin-bottom:7px}input{width:100%;min-height:48px;border:1px solid rgba(255,255,255,.18);border-radius:10px;background:#11151b;color:#fff;padding:10px 12px;font-size:16px}.results{display:grid;gap:8px;margin-top:10px}.result{width:100%;text-align:left;padding:12px;border:1px solid rgba(255,255,255,.15);border-radius:10px;background:#11151b;color:#fff}.result.selected{border-color:var(--gold);background:#211b09}.drop{display:grid;place-items:center;min-height:170px;border:2px dashed rgba(255,191,0,.5);border-radius:14px;background:#0b0e12;text-align:center;padding:18px}.drop.drag{border-color:var(--green)}.preview{display:none;grid-template-columns:150px 1fr;gap:16px;align-items:center;margin-top:18px;padding:14px;border:1px solid var(--border);border-radius:14px}.preview img{width:150px;height:150px;object-fit:cover;border-radius:12px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}button{font:inherit;cursor:pointer}.secondary{padding:12px 18px;border-radius:10px;border:1px solid var(--border);background:#11151b;color:#fff;font-weight:800}.status{margin-top:14px;min-height:22px}.error{color:#ff9b9b}.success{color:#7df0ae}@media(max-width:560px){main{margin:14px auto}.panel{padding:14px}.preview{grid-template-columns:1fr}.preview img{width:100%;height:auto;aspect-ratio:1/1}}</style></head><body>' +
    '<header><a class="brand" href="https://app.saysaymusic.com/"><img src="https://audio.saysaymusic.com/Logo_New1.png" alt=""><span>SaySayMusic Studio</span></a><a class="app-link" href="https://app.saysaymusic.com/">Back to App</a></header>' +
    '<main><section class="panel"><h1>Free Song of the Week</h1><div class="muted">Select one song, add its cover, preview, and publish.</div><div id="gate" class="status">Checking administrator access…</div>' +
    '<div id="tool" hidden><div class="field"><label for="search">1. Search for a song</label><input id="search" type="search" placeholder="Enter the song title"><div id="results" class="results"></div></div>' +
    '<div class="field"><label for="cover">2. Add the cover</label><div id="drop" class="drop"><div><strong>Drag and drop the cover here</strong><br><span class="muted">or choose a JPG, PNG, or WebP file</span><br><br><input id="cover" type="file" accept="image/jpeg,image/png,image/webp"></div></div></div>' +
    '<div id="preview" class="preview"><img id="previewImage" alt="Selected cover preview"><div><div class="muted">Selected song</div><h2 id="previewTitle"></h2><div id="previewMeta" class="muted"></div></div></div>' +
    '<div class="actions"><button id="publish" class="primary" disabled>Publish Free Song</button><a class="secondary" href="/free-song" target="_blank" rel="noopener">Open Current Page</a></div><div id="status" class="status" aria-live="polite"></div></div></section></main><footer>SaySayMusic — Education Through Melody</footer>' +
    '<script>(function(){var API="https://stream.saysaymusic.com",selected=null,coverData="",timer=null;var gate=document.getElementById("gate"),tool=document.getElementById("tool"),search=document.getElementById("search"),results=document.getElementById("results"),cover=document.getElementById("cover"),drop=document.getElementById("drop"),preview=document.getElementById("preview"),previewImage=document.getElementById("previewImage"),previewTitle=document.getElementById("previewTitle"),previewMeta=document.getElementById("previewMeta"),publish=document.getElementById("publish"),status=document.getElementById("status");function ready(){publish.disabled=!(selected&&coverData);if(selected){preview.style.display="grid";previewTitle.textContent=selected.title||"Featured Song";previewMeta.textContent=(selected.artist||"SaySayMusic")+(selected.subject?" · "+selected.subject:"")}}function message(text,kind){status.textContent=text;status.className="status "+(kind||"")}function choose(song,button){selected=song;results.querySelectorAll(".result").forEach(function(x){x.classList.remove("selected")});button.classList.add("selected");ready()}function render(list){results.innerHTML="";(list||[]).slice(0,20).forEach(function(song){var b=document.createElement("button");b.type="button";b.className="result";b.textContent=(song.title||"Untitled")+" — "+(song.artist||"SaySayMusic");b.onclick=function(){choose(song,b)};results.appendChild(b)});if(!list||!list.length)results.textContent="No songs found."}function loadFile(file){if(!file)return;if(!/^image\\/(jpeg|png|webp)$/.test(file.type)){message("Choose a JPG, PNG, or WebP image.","error");return}if(file.size>5*1024*1024){message("Cover must be 5 MB or smaller.","error");return}var reader=new FileReader();reader.onload=function(){coverData=String(reader.result||"");previewImage.src=coverData;message("Cover ready.","success");ready()};reader.readAsDataURL(file)}fetch(API+"/api/me",{credentials:"include"}).then(function(r){return r.json()}).then(function(out){if(!out.user||String(out.user.role||"").toLowerCase()!=="admin")throw new Error("Administrator login required.");gate.textContent="";tool.hidden=false}).catch(function(e){gate.textContent=e.message;gate.className="status error"});search.addEventListener("input",function(){clearTimeout(timer);var q=search.value.trim();if(q.length<2){results.innerHTML="";return}timer=setTimeout(function(){fetch(API+"/api/tracks?limit=50&q="+encodeURIComponent(q),{credentials:"include"}).then(function(r){return r.json()}).then(function(out){render(out.tracks||[])}).catch(function(){message("Song search failed.","error")})},300)});cover.addEventListener("change",function(){loadFile(cover.files&&cover.files[0])});["dragenter","dragover"].forEach(function(type){drop.addEventListener(type,function(e){e.preventDefault();drop.classList.add("drag")})});["dragleave","drop"].forEach(function(type){drop.addEventListener(type,function(e){e.preventDefault();drop.classList.remove("drag")})});drop.addEventListener("drop",function(e){loadFile(e.dataTransfer.files&&e.dataTransfer.files[0])});publish.addEventListener("click",function(){if(!selected||!coverData)return;publish.disabled=true;message("Publishing…","");fetch(API+"/api/admin/featured-song",{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({track_id:selected.id,cover_data_url:coverData})}).then(function(r){return r.json().then(function(body){if(!r.ok||!body.ok)throw new Error(body.error||"Publish failed");return body})}).then(function(){message("Published successfully. The permanent free-song link is updated.","success");publish.disabled=false}).catch(function(e){message(e.message,"error");publish.disabled=false})})})();</script></body></html>';
  return new Response(html, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" } });
}

export default {
  fetch(request) {
    const path = new URL(request.url).pathname;
    if (path === "/free-song-cover.jpg") return coverResponse();
    if (path === "/studio/free-song") return adminPage();
    return publicPage();
  }
};
